INSERT INTO `monhoc` (`id_monhoc`, `tenmonhoc`, `mieuta`, `id_nguoidung`, `ngaythem`) VALUES
(6, 'Lập trình PHP', 'Lập trình web phía server với PHP: xử lý form, session, kết nối MySQL, CRUD, upload file và xây dựng website động.', 23, '2026-03-21 18:08:17'),
(7, 'Cơ sở dữ liệu MySQL', 'Học thiết kế cơ sở dữ liệu, ngôn ngữ SQL, truy vấn nâng cao, transaction và quản trị MySQL.', 23, '2026-03-21 18:08:08'),
(8, 'Cấu trúc dữ liệu và giải thuật', 'Học các cấu trúc dữ liệu (stack, queue, cây, đồ thị…) và thuật toán quan trọng để giải quyết vấn đề hiệu quả.', 23, '2026-03-21 18:08:11'),
(9, 'Mạng máy tính', 'Nghiên cứu kiến trúc mạng, giao thức TCP/IP, định tuyến, mạng LAN/WAN và bảo mật mạng cơ bản.', 23, '2026-03-21 18:08:13'),
(10, 'Trí tuệ nhân tạo', 'Giới thiệu nền tảng Trí tuệ Nhân tạo, bao gồm tìm kiếm, học máy, mạng nơ-ron và các ứng dụng AI thực tế.', 23, '2026-03-21 18:08:15');
